function nextArrangement(nums: number[]): void {
  const sorted = [...nums].sort((a, b) => a - b);
  const used = new Array(sorted.length).fill(false), path: number[] = [];
  let found: number[] | null = null;
  const bigger = (p: number[]): boolean => {
    for (let i = 0; i < p.length; i++) if (p[i] !== nums[i]) return p[i] > nums[i];
    return false;
  };
  const walk = (): boolean => {
    if (path.length === sorted.length) {
      if (bigger(path)) { found = [...path]; return true; }
      return false;
    }
    for (let i = 0; i < sorted.length; i++) {
      if (used[i] || (i > 0 && sorted[i] === sorted[i - 1] && !used[i - 1])) continue;
      used[i] = true; path.push(sorted[i]);
      if (walk()) return true;
      used[i] = false; path.pop();
    }
    return false;
  };
  walk();
  const res: number[] = found ?? sorted;
  for (let i = 0; i < nums.length; i++) nums[i] = res[i];
}

